using System.Collections.Generic;
using CadAI.AutoCAD.Dto;
using CadAI.AutoCAD.Edits;
using Xunit;

namespace CadAI.AutoCAD.Tests.Edits;

/// <summary>
/// Proves the plugin's <see cref="PreImageCanonical"/> port is byte-identical to the Cloud-side
/// canonicalizer (packages/engineering/src/spatial/fingerprint.ts) that the Design Guard already
/// uses to bind validation records to payloads. The digests in the shared fixture are generated by
/// that TypeScript function, not hand-written, so reproducing them here is the load-bearing claim
/// for the edit flow: Cloud stores only a pre-image digest (the payload stays local per the epic
/// decision), and the restore path re-computes it in the plugin — the two must agree bit for bit,
/// or an edit could be restored against an entity that is not the one the user approved.
/// The mirror-image assertion lives in packages/engineering/tests/preimage-fingerprint-parity.test.ts.
/// </summary>
public class PreImageCanonicalTests
{
    private static string Digest(string name) => PreImageCanonical.HashCanonical(ContractFixtures.DigestValue(name));

    public static IEnumerable<object[]> Vectors() =>
        ContractFixtures.DigestVectors.Select(v => new object[] { v["name"]!.ToString(), v["expectedDigest"]!.ToString() });

    [Theory]
    [MemberData(nameof(Vectors))]
    public void CanonicalPort_ReproducesTheCloudFingerprintDigest(string name, string expectedDigest)
    {
        // The fixture payloads are camelCase wire JSON, so they canonicalize directly — this is the
        // exact form Fingerprint(EntityPreImage) produces after camelCase serialization of Detail.
        Assert.Equal(expectedDigest, Digest(name));
    }

    [Fact]
    public void FloatWobble_SameRoundedValue_DigestsEqual()
        => Assert.Equal(Digest("line"), Digest("line-float-wobble-equals-line"));

    [Fact]
    public void MovedVertex_DigestsDiffer()
        => Assert.NotEqual(Digest("line"), Digest("line-moved-differs-from-line"));

    [Fact]
    public void VolatileKeys_DroppedAndDoNotChangeTheDigest()
        => Assert.Equal(Digest("circle-volatile-dropped"), Digest("circle-volatile-free-equals-volatile-dropped"));

    [Fact]
    public void ExplicitNull_AndAbsentKey_DigestDifferently()
        => Assert.NotEqual(Digest("circle-volatile-dropped"), Digest("circle-bounds-null-vs-absent-differs"));

    [Fact]
    public void VertexOrder_IsSemantic_ReversalChangesDigest()
    {
        // Arrays are order-preserving: reversing a polyline's vertices is a different shape, not the
        // same drawing read in another order (unlike entity ordering in drawingFingerprint).
        var forward = ContractFixtures.DigestValue("polyline-order-is-semantic");
        var reversed = (Newtonsoft.Json.Linq.JObject)forward.DeepClone();
        var verts = (Newtonsoft.Json.Linq.JArray)reversed["geometry"]!["vertices"]!;
        reversed["geometry"]!["vertices"] = new Newtonsoft.Json.Linq.JArray(System.Linq.Enumerable.Reverse(verts));
        Assert.NotEqual(PreImageCanonical.HashCanonical(forward), PreImageCanonical.HashCanonical(reversed));
    }

    [Fact]
    public void UnicodeAndEscapedQuotes_CanonicalizeToTheCloudForm()
    {
        // The text vector carries a quote, newline, tab, an em dash and CJK — the two escape paths
        // (JSON.stringify vs EscapeJson) must agree or the digest would drift for real MText.
        Assert.Equal(Digest("text-unicode-and-quotes"), PreImageCanonical.HashCanonical(ContractFixtures.DigestValue("text-unicode-and-quotes")));
    }

    [Fact]
    public void NegativeHalf_RoundsTowardPositiveInfinityLikeJsMathRound()
    {
        // -0.5000005 must render -0.500000 (Js Math.round sends the half toward +infinity), and a
        // half below zero (-0.0000005) collapses to +0.000000 exactly as (-0).toFixed(6) does in JS.
        // AwayFromZero would give -0.500001 / -0.000000 and split C# from TS. The digest theory pins
        // this too; these substring checks make the intent readable when it regresses.
        var canonical = PreImageCanonical.Canonicalize(ContractFixtures.DigestValue("line-negative-half"));
        Assert.Contains("\"x\":-0.500000", canonical);
        Assert.Contains("\"y\":0.000000", canonical);
    }

    [Fact]
    public void Fingerprint_IsStableAcrossTwoCaptures_AndSensitiveToACoordinate()
    {
        var a = Line("2a4", 0, 0);
        Assert.Equal(PreImageCanonical.Fingerprint(a), PreImageCanonical.Fingerprint(Line("2a4", 0, 0)));
        Assert.NotEqual(PreImageCanonical.Fingerprint(a), PreImageCanonical.Fingerprint(Line("2a4", 0, 5)));

        // Capture metadata is deliberately outside the Detail digest, so restamping cannot move it.
        var reStamped = Line("2a4", 0, 0);
        reStamped.CapturedAtUtc = "2099-01-01T00:00:00Z";
        Assert.Equal(PreImageCanonical.Fingerprint(a), PreImageCanonical.Fingerprint(reStamped));
    }

    [Fact]
    public void Fingerprint_OfALineDetail_MatchesTheFixtureVector()
    {
        // The DTO-serialized path (Fingerprint) and the raw-JSON path (HashCanonical on the fixture
        // value) must land on the same digest for the same line — this is what makes the plugin's
        // capture and Cloud's mirror interchangeable.
        Assert.Equal(Digest("line"), PreImageCanonical.Fingerprint(Line("2a4", 100.5, 0.3)));
    }

    private static EntityPreImage Line(string handle, double x2, double y2) => new()
    {
        CapturedAtUtc = "2026-10-24T00:00:00Z",
        Detail = new EntityDetailDto
        {
            Handle = handle,
            Kind = "line",
            Layer = "WALLS",
            Geometry = new LineGeometryDto
            {
                Start = new Point3dDto { X = 0, Y = 0, Z = 0 },
                End = new Point3dDto { X = x2, Y = y2, Z = 0 },
                Length = 100.5004,
            },
            Properties = new EntityPropertiesDto
            {
                Color = new ColorSpecDto { Aci = 256 },
                Linetype = "ByLayer",
                LinetypeScale = 1,
                Lineweight = -1,
                Visible = true,
            },
        },
    };
}
